+import 'package:flutter_test/flutter_test.dart';
+
+import 'golden_test_helper.dart';
+
+void main() {
+  setUpAll(ensureGoldenFonts);
+
+  testWidgets('load confirmation with a declared network capability', (
+    tester,
+  ) async {
+    await pumpGolden(
+      tester,
+      UnpackedLoadConfirmDialog(
