+        name: 'FA Agents',
+        version: '0.3.0',
+        network: true,
+      ),
+      size: goldenSizeTall,
+    );
+    await expectGolden(tester, 'unpacked_load_confirm_network');
+  });
+
+  testWidgets('load confirmation warns when an existing id is replaced', (
+    tester,
+  ) async {
+    await pumpGolden(
