        // flagged entry, one construction site (issue #866 review r2).
        _refHashes.remove(id);
        app = JsAppInfo(
          id: id,
          name: id,
          description: '',
          icon: '📦',
          declaredPermissions: const AppPermissions(),
          error: e is FormatException
              ? 'manifest.json does not parse: ${e.message}'
