            'manifest.json': utf8.encode(
              jsonEncode({
                'id': 'fa-agents',
                'name': 'FA Agents',
                'widget': {'entry': 'widget_tile.js', 'refreshSeconds': 15},
              }),
            ),
            'widget.js': utf8.encode('jsr.render(null);'),
