}) async {
  TestWidgetsFlutterBinding.ensureInitialized();
  final env = MemoryExecutionEnv();
  final manager = FlutterSessionManager(env: env, sessionsRoot: '/sessions');
  manager.addSession('test-session', _fakeService(env));
